begin;
create extension if not exists pgtap with schema extensions;
select plan(21);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','a1000000-0000-4000-8000-000000000001','authenticated','authenticated','accounting-owner@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_business('accounting-test','Accounting Test Inc','Accounting Test','corporation','retail','{"city":"Manila"}');
select set_config('test.acc_org',(select id::text from public.organizations where slug='accounting-test'),true);select set_config('test.acc_branch',(select id::text from public.branches where organization_id=current_setting('test.acc_org')::uuid and code='main'),true);
reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.acc_org')::uuid,'internal','multi_branch','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);
select public.set_business_module_state(current_setting('test.acc_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.acc_org')::uuid,'inventory',true,'{}');select public.set_business_module_state(current_setting('test.acc_org')::uuid,'sales',true,'{}');select public.set_business_module_state(current_setting('test.acc_org')::uuid,'pos',true,'{}');select public.set_business_module_state(current_setting('test.acc_org')::uuid,'expenses',true,'{"approval_threshold":0}');select public.set_business_module_state(current_setting('test.acc_org')::uuid,'invoicing',true,'{"payment_terms_days":30}');select public.set_business_module_state(current_setting('test.acc_org')::uuid,'purchasing',true,'{}');
select lives_ok($$select public.set_business_module_state(current_setting('test.acc_org')::uuid,'accounting',true,'{"posting_detail":"document"}')$$,'Accounting activates after operational dependencies');
select is(public.can_business_permission(current_setting('test.acc_org')::uuid,'accounting.close'),true,'Owner receives period-close permission');
select results_eq($$select count(*)from public.accounting_accounts where organization_id=current_setting('test.acc_org')::uuid$$,$$select 25::bigint$$,'Activation seeds the locked SME chart of accounts');
select throws_ok($$select public.activate_accounting(current_setting('test.acc_org')::uuid,current_date,'[{"accountKey":"cash","debit":100,"credit":0},{"accountKey":"owner_equity","debit":0,"credit":90}]')$$,'23514','Opening balances are not balanced.','Unbalanced cutover is rejected');
select set_config('test.opening',public.activate_accounting(current_setting('test.acc_org')::uuid,current_date,'[{"accountKey":"cash","debit":1000,"credit":0},{"accountKey":"owner_equity","debit":0,"credit":1000}]')::text,true);
select results_eq($$select status,activation_date from public.accounting_settings where organization_id=current_setting('test.acc_org')::uuid$$,$$select 'active'::text,current_date$$,'Reviewed opening balances activate the ledger');
select results_eq($$select sum(debit),sum(credit)from public.journal_lines where entry_id=current_setting('test.opening')::uuid$$,$$select 1000::numeric,1000::numeric$$,'Opening journal is balanced');
select set_config('test.manual',public.save_manual_journal(current_setting('test.acc_org')::uuid,current_setting('test.acc_branch')::uuid,current_date,'Record bank transfer','[{"accountKey":"bank","debit":250,"credit":0},{"accountKey":"cash","debit":0,"credit":250}]','manual-transfer-001')::text,true);
select results_eq($$select public.save_manual_journal(current_setting('test.acc_org')::uuid,current_setting('test.acc_branch')::uuid,current_date,'Replay','[{"accountKey":"bank","debit":250,"credit":0},{"accountKey":"cash","debit":0,"credit":250}]','manual-transfer-001')$$,$$select current_setting('test.manual')::uuid$$,'Manual journal replay returns the original entry');
select throws_ok($$update public.journal_lines set debit=1 where entry_id=current_setting('test.manual')::uuid and debit>0$$,'42501','permission denied for table journal_lines','Clients cannot mutate journal lines');
select set_config('test.period',(select id::text from public.accounting_periods where organization_id=current_setting('test.acc_org')::uuid and current_date between starts_on and ends_on),true);
select lives_ok($$select public.set_accounting_period_status(current_setting('test.acc_org')::uuid,current_setting('test.period')::uuid,'closed')$$,'Authorized user closes a period');
select throws_ok($$select public.save_manual_journal(current_setting('test.acc_org')::uuid,null,current_date,'Closed period entry','[{"accountKey":"cash","debit":10,"credit":0},{"accountKey":"owner_equity","debit":0,"credit":10}]','closed-period-001')$$,'P0001','Accounting period is closed.','Closed periods reject posting');
select public.set_accounting_period_status(current_setting('test.acc_org')::uuid,current_setting('test.period')::uuid,'open');
select set_config('test.product',public.save_catalog_product(current_setting('test.acc_org')::uuid,null,null,'product','Taxed Item','',null,null,'piece',112,60,'inclusive',12,'active',false,'[{"name":"Default","sku":"ACC-001","barcode":"","attributes":{},"status":"active"}]','[]')::text,true);select set_config('test.variant',(select id::text from public.product_variants where product_id=current_setting('test.product')::uuid),true);select set_config('test.location',(select id::text from public.inventory_locations where organization_id=current_setting('test.acc_org')::uuid),true);select set_config('test.item',public.configure_inventory_item(current_setting('test.acc_org')::uuid,null,current_setting('test.variant')::uuid,0,0,true)::text,true);select public.record_stock_movement(current_setting('test.acc_org')::uuid,current_setting('test.item')::uuid,current_setting('test.location')::uuid,'opening_balance',10,60,'Opening','acc-stock-opening');
select set_config('test.sale',public.save_pos_transaction(current_setting('test.acc_org')::uuid,null,current_setting('test.acc_branch')::uuid,current_setting('test.location')::uuid,null,'completed','a1000000-0000-4000-8000-000000000101',now(),('[{"productVariantId":"'||current_setting('test.variant')||'","quantity":1,"discountAmount":0}]')::jsonb,'[{"method":"cash","amount":112,"reference":""}]')::text,true);
select is((public.accounting_dashboard(current_setting('test.acc_org')::uuid)->>'pendingEvents')::integer,1,'Completed sale emits one accounting event');
select is((public.process_accounting_events(current_setting('test.acc_org')::uuid,50)->>'failed')::integer,0,'Accounting processor reports no failures');
select results_eq($$select sum(line.debit),sum(line.credit)from public.journal_entries entry join public.journal_lines line on line.entry_id=entry.id where entry.source_key='sale:completed:'||current_setting('test.sale')$$,$$select 172::numeric,172::numeric$$,'Cash sale posts revenue, tax, COGS, and inventory');
select results_eq($$select count(*)from public.journal_entries where source_key='sale:completed:'||current_setting('test.sale')$$,$$select 1::bigint$$,'Event retry cannot duplicate the sale journal');
select is((public.financial_report(current_setting('test.acc_org')::uuid,'trial_balance',current_date,current_date,null)->>'totalDebit')::numeric,(public.financial_report(current_setting('test.acc_org')::uuid,'trial_balance',current_date,current_date,null)->>'totalCredit')::numeric,'Trial balance remains balanced');
select set_config('test.supplier',public.save_supplier(current_setting('test.acc_org')::uuid,null,'Supplier One','','','','','',30,'active','')::text,true);
select set_config('test.invoice',public.save_supplier_invoice(current_setting('test.acc_org')::uuid,current_setting('test.acc_branch')::uuid,current_setting('test.supplier')::uuid,null,'SUP-001',current_date,current_date+30,500,60,'')::text,true);
select public.process_accounting_events(current_setting('test.acc_org')::uuid,50);
select results_eq($$select balance_due,status from public.supplier_invoices where id=current_setting('test.invoice')::uuid$$,$$select 560::numeric,'issued'::text$$,'Supplier invoice starts as an open payable');
select set_config('test.supplier_payment',public.record_supplier_payment(current_setting('test.acc_org')::uuid,current_setting('test.acc_branch')::uuid,current_setting('test.supplier')::uuid,current_date,'bank_transfer','PAY-1',200,('[{"supplierInvoiceId":"'||current_setting('test.invoice')||'","amount":200}]')::jsonb,'supplier-payment-001')::text,true);
select results_eq($$select amount_paid,balance_due,status from public.supplier_invoices where id=current_setting('test.invoice')::uuid$$,$$select 200::numeric,360::numeric,'partially_paid'::text$$,'Supplier payment allocates atomically');
select is((public.accounting_dashboard(current_setting('test.acc_org')::uuid)->>'pendingEvents')::integer,1,'Supplier payment emits one posting event');
select set_config('test.bank',public.save_bank_account(current_setting('test.acc_org')::uuid,null,current_setting('test.acc_branch')::uuid,'Operating Account','Test Bank','1234',0)::text,true);
select is(public.import_bank_transactions(current_setting('test.acc_org')::uuid,current_setting('test.bank')::uuid,'[{"date":"2026-08-31","description":"Deposit","reference":"D1","amount":250,"externalKey":"bank-1"}]'),1,'Bank statement row imports');
select is(public.import_bank_transactions(current_setting('test.acc_org')::uuid,current_setting('test.bank')::uuid,'[{"date":"2026-08-31","description":"Deposit","reference":"D1","amount":250,"externalKey":"bank-1"}]'),0,'Bank import replay is idempotent');
select is((public.accounting_dashboard(current_setting('test.acc_org')::uuid)->>'unmatchedBankTransactions')::integer,1,'Dashboard exposes unmatched bank work');
select * from finish();rollback;
